-- ============================================
-- LUMA — Thème 14 : MOYEN 2/3 x4 — Rencontrer des locaux dans une petite ville
-- ============================================


update scenarios set content = '{"characters": {"local1": "local 1", "local2": "local 2"}, "start_node": "n1", "nodes": {"n1": {"speaker": "local1", "text": "Well, you don''t look like you''re from around here! Passing through?", "text_fr": "Bon, vous avez pas l''air d''être du coin ! Vous êtes de passage ?", "choices": [{"text": "Yeah, on a road trip actually, exploring small towns along the way.", "text_fr": "Ouais, en road trip en fait, j''explore les petites villes en chemin.", "next": "n2"}, {"text": "I am! This town is beautiful, how long have you lived here?", "text_fr": "Oui ! Cette ville est magnifique, ça fait longtemps que vous vivez ici ?", "next": "n2b"}]}, "n2": {"speaker": "local1", "text": "That''s wonderful! Most travelers just stick to the highways, missing places like this.", "text_fr": "C''est merveilleux ! La plupart des voyageurs restent sur les autoroutes, ratant des endroits comme ça.", "choices": [{"text": "Exactly why I wanted to take the scenic route this time.", "text_fr": "Exactement pourquoi je voulais prendre la route pittoresque cette fois.", "next": "n3"}]}, "n2b": {"speaker": "local1", "text": "My whole life, actually! Born and raised right here in this town.", "text_fr": "Toute ma vie, en fait ! Né et élevé juste ici dans cette ville.", "choices": [{"text": "That''s amazing, what''s your favorite thing about living here?", "text_fr": "C''est génial, qu''est-ce que vous préférez dans le fait de vivre ici ?", "next": "n3"}]}, "n3": {"speaker": "local1", "text": "You should check out the diner on Main Street, best pie in three counties!", "text_fr": "Vous devriez aller voir le diner sur Main Street, la meilleure tarte à trois comtés à la ronde !", "choices": [{"text": "I''ll definitely check that out, thank you for the recommendation.", "text_fr": "Je vais définitivement aller voir ça, merci pour la recommandation.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(Later, at the diner, another local strikes up conversation.)", "text_fr": "(Plus tard, au diner, un autre local engage la conversation.)", "choices": [{"text": "(Order the famous pie and chat with nearby locals.)", "text_fr": "(Commande la fameuse tarte et discute avec les locaux à proximité.)", "next": "n5"}]}, "n5": {"speaker": "local2", "text": "First time trying our pie? You picked a good day, fresh batch this morning!", "text_fr": "Première fois que vous essayez notre tarte ? Vous avez choisi un bon jour, fournée fraîche ce matin !", "choices": [{"text": "I can''t wait to try it! This town has such a warm feeling to it.", "text_fr": "J''ai hâte de l''essayer ! Cette ville a une ambiance tellement chaleureuse.", "next": "n6"}]}, "n6": {"speaker": "local2", "text": "That''s small town life for you! Everyone knows everyone, mostly in a good way.", "text_fr": "C''est la vie de petite ville pour vous ! Tout le monde connaît tout le monde, surtout dans le bon sens.", "choices": [{"text": "I can definitely feel that. It''s a nice change from city life.", "text_fr": "Je peux définitivement le ressentir. C''est un joli changement par rapport à la vie citadine.", "next": "n7"}]}, "n7": {"speaker": "local2", "text": "If you''re sticking around tonight, there''s a little community gathering at the square.", "text_fr": "Si vous restez ce soir, il y a un petit rassemblement communautaire sur la place.", "choices": [{"text": "That sounds lovely, I might just stay to check it out.", "text_fr": "Ça a l''air adorable, je pourrais bien rester pour aller voir ça.", "next": "n8"}, {"text": "I wish I could, but I have to keep moving on my route today.", "text_fr": "J''aimerais bien, mais je dois continuer ma route aujourd''hui.", "next": "n8"}]}, "n8": {"speaker": "local1", "text": "(Rejoins) Either way, glad you stopped by our little town, even briefly!", "text_fr": "(Rejoint) Dans tous les cas, content que vous vous soyez arrêté dans notre petite ville, même brièvement !", "choices": [{"text": "Me too, honestly. This might be my favorite stop of the whole trip.", "text_fr": "Moi aussi, honnêtement. Ça pourrait être mon arrêt préféré de tout le voyage.", "next": "end_welcomed"}]}, "end_welcomed": {"speaker": "local2", "text": "That means a lot to hear. Safe travels, and come back anytime!", "text_fr": "Ça compte beaucoup à entendre. Bonne route, et revenez quand vous voulez !", "end": true, "ending_label": "Accueil chaleureux dans une petite ville américaine 🏘️❤️"}}}'::jsonb, is_playable = true
where title = 'Rencontrer des locaux dans une petite ville'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
